function decode(text,encoding){if(encoding==='base64'){const raw=atob(text.replace(/\s/g,''));return new TextDecoder().decode(Uint8Array.from(raw,c=>c.charCodeAt(0)));}if(encoding==='quoted-printable'){const raw=text.replace(/=\r?\n/g,'').replace(/=([0-9A-F]{2})/gi,(_,h)=>String.fromCharCode(parseInt(h,16)));return new TextDecoder().decode(Uint8Array.from(raw,c=>c.charCodeAt(0)));}return text;}
export function importEmail(source){if(typeof source!=='string'||source.length>65536)throw Error('Use an email file smaller than 64 KB.');const normalized=source.replace(/\r\n/g,'\n');const at=normalized.indexOf('\n\n');if(at<0)return normalized;const headers=normalized.slice(0,at).replace(/\n[ \t]+/g,' '),body=normalized.slice(at+2);const type=(headers.match(/^Content-Type:\s*(.*)$/im)?.[1]||'text/plain');if(/multipart/i.test(type)){const boundary=type.match(/boundary\s*=\s*"?([^";\s]+)/i)?.[1];if(!boundary)throw Error('This email has no readable plain-text part. Paste its text instead.');for(const part of body.split('--'+boundary)){if(/^Content-Type:\s*text\/plain/im.test(part)){const extracted=importEmail(part.trim());return [headers.match(/^Subject:.*$/im)?.[0],headers.match(/^From:.*$/im)?.[0],extracted].filter(Boolean).join('\n');}}throw Error('This email has no plain-text part. Copy and paste its text instead.');}if(!/^text\/plain/i.test(type))throw Error('Only plain-text email parts are supported. Copy and paste the message text instead.');const encoding=(headers.match(/^Content-Transfer-Encoding:\s*(.*)$/im)?.[1]||'').trim().toLowerCase();return [headers.match(/^Subject:.*$/im)?.[0],headers.match(/^From:.*$/im)?.[0],decode(body,encoding)].filter(Boolean).join('\n');}
